local RectTransform = CS.UnityEngine.RectTransform
local KTool = CS.Engine.Lib.KTool
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule

local CDTimerModule = CS.Engine.Modules.CDTimerModule
local TimeZoneUtils = CS.Engine.Http.TimeZoneUtils
local DailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
------------ import ------------

---@class UIFightMapDailyQuestCell
---@field LockText                      	UnityEngine.RectTransform               
---@field text                          	UnityEngine.RectTransform               
---@field finishImg                     	UnityEngine.RectTransform               
---@field bg                            	UnityEngine.RectTransform               
---@field entrust                       	UnityEngine.RectTransform               
---@field startRoot                     	UnityEngine.RectTransform               
---@field titlebg                       	UnityEngine.RectTransform               
---@field bigRewardBg                   	UnityEngine.RectTransform               
---@field curQuestIma                   	UnityEngine.RectTransform               
---@field ima                           	UnityEngine.RectTransform               
---@field rewardBg                      	UnityEngine.RectTransform               
---@field questLabel                    	UnityEngine.RectTransform               
---@field rewardIcon                    	Engine.UI.ImageAlterable                
---@field lock                          	UnityEngine.RectTransform               
---@field unLock                        	UnityEngine.RectTransform               
local UIFightMapDailyQuestCell = Class("UIFightMapDailyQuestCell")

function UIFightMapDailyQuestCell:__init()
    self._questVo = nil
    self._time = nil
    self._isCopyOpen = nil     --副本是否开放
    self._isCopyUnlcok = nil   --副本是否解锁
end

function UIFightMapDailyQuestCell:__delete()
    self._questVo = nil
    self._time = nil
    self._isCopyOpen = nil     
    self._isCopyUnlcok = nil     
end

function UIFightMapDailyQuestCell:Awake()
end

---@param questId integer @ 关卡ID
---@param isCurChallengeQuestId boolean
function UIFightMapDailyQuestCell:RefreshLevelInfo(questId, isCurChallengeQuestId)
    if not isNull(self) then
        ---删除计时器
        CDTimerModule.GetInstance():RemoveCD(self._time)
    end

    self._questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not self._questVo then
        return
    end

    local dojo = DailyQuestComponent:GetDailyQuestDojoByType(self._questVo.type)
    if not dojo then
        return
    end
    self._isCopyOpen = checkNumber(dojo.open) == 1
    self._isCopyUnlcok = checkNumber(dojo.unlock) == 1

    --位置
    local pos = CfUtils.Split(self._questVo.location)
    if pos then
        self.controller.gameObject:GetComponent(typeof(RectTransform)).anchoredPosition3D = Vector3.New(checkNumber(pos[1]), checkNumber(pos[2]), 0)
    end
    CfUtils.FillText(self.questLabel, self._questVo.label)
    
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._questVo.id) 
    local isUnlockLevel = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PlayerLevel, checkString(self._questVo.level))
    KTool.SetActive(self.lock.gameObject, (not isUnlock or not isUnlockLevel or not self._isCopyOpen or not self._isCopyUnlcok))
    --如果解锁
    if self._isCopyOpen and self._isCopyUnlcok and isUnlock and isUnlockLevel then
        local isPass = QuestConfMgr:GetInstance():IsPassQuest(self._questVo.id)
        KTool.SetActive(self.startRoot.gameObject, isPass)

        --如果通关
        if isPass then
            CfUtils.FillImage(self.ima, "uiatlas/BattleSelection/FightMap/map_jpg_pass_2.png")
            local condtitions = QuestConfMgr:GetInstance():GetQuestConditions(self._questVo.id)
            if condtitions then
                local count = 0
                for k, v in pairs(condtitions) do
                    local isComplete = QuestConfMgr:GetInstance():IsCompleteCondition(questId, v.id)
                    if isComplete then
                        count = count + 1
                    end
                end

                for i = 1, 3 do
                    CfUtils.FillImage(self.startRoot.transform:Find("start"..i), (i <= count) and "uiatlas/BattleSelection/FightMap/map_img_star2.png" or "uiatlas/BattleSelection/FightMap/map_img_star.png")
                end 
            end
        else
            CfUtils.FillImage(self.ima, "uiatlas/BattleSelection/FightMap/map_jpg_dangqian.png")
        end

        if isCurChallengeQuestId then
            self:SetCurLevelStatues(true)
        else
            self:SetCurLevelStatues(false)
        end
    else
        self:SetCurLevelStatues(false)
        KTool.SetActive(self.startRoot.gameObject, false)
        CfUtils.FillImage(self.ima, "uiatlas/BattleSelection/FightMap/map_jpg_lock_2.png")

        KTool.SetActive(self.LockText, not isUnlockLevel)
        if not isUnlockLevel then
            CfUtils.FillText(self.LockText, GameUtils.GetUnlockDescr("1", checkString(self._questVo.level)))
        end
    end

    --奖励显示
    local rewardGood = RewardConfMgr:GetQuestRewardData(self._questVo.id, Constants.QuestRewardType.RegularReward, true)
    if rewardGood then
        local photoPath
        if #rewardGood > 0 then
            photoPath = GoodsConfMgr:GetInstance():GetPhotoPathById(rewardGood[1].id)
        end
        CfUtils.FillImage(self.rewardIcon, photoPath)
    else
        --没有奖励隐藏
        KTool.SetActive(self.rewardIcon.gameObject, false)
        KTool.SetActive(self.rewardBg.gameObject, false)
    end
    
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = Bind(self, self.OnBtnGo) -- 整个
    self:FillEnquestInfo()
end

--绘制委托信息  
function UIFightMapDailyQuestCell:FillEnquestInfo()
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local dojo = teamComponent:GetEntrustQueueDataByQuestId(self._questVo.id)
    if dojo then
        --如果完成了
        if TimeZoneUtils.UtcSeconds >= checkNumber(dojo.expirationTime) then
            --CfUtils.FillImage(self.bg, "uiatlas/BattleSelection/FightMap/map_bg_auto_finish.png")
            KTool.SetActive(self.finishImg, true)
            CfUtils.FillText(self.text, localize("委托完成"))
        else
            --CfUtils.FillImage(self.bg, "uiatlas/BattleSelection/FightMap/map_bg_autoing.png")
            KTool.SetActive(self.finishImg, false)
            CfUtils.FillText(self.text, CfUtils.GetTimeHMS(checkNumber(dojo.expirationTime) - TimeZoneUtils.UtcSeconds))

            --计时器
            self._time = CDTimerModule.GetInstance():AddCD(1, function(count, id)
                local residueTime = checkNumber(dojo.expirationTime) - TimeZoneUtils.UtcSeconds
                --如果剩余时间大于0  显示倒计时
                if residueTime > 0 then
                    CfUtils.FillText(self.text, CfUtils.GetTimeHMS(residueTime))
                else
                    CfUtils.FillImage(self.bg, "uiatlas/BattleSelection/FightMap/map_bg_auto_finish.png")
                    KTool.SetActive(self.finishImg, true)
                    CfUtils.FillText(self.text, localize("委托完成"))
                end
            end, 604800, false, true, true)
        end
        
        KTool.SetActive(self.entrust, true)
    else
        KTool.SetActive(self.entrust, false)
    end
end

function UIFightMapDailyQuestCell:OnBtnGo()
    if not self._questVo then
        return
    end

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(self._questVo.id)
    local isUnlockLevel = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PlayerLevel, checkString(self._questVo.level))
    --如果解锁
    if isUnlock and isUnlockLevel and self._isCopyOpen and self._isCopyUnlcok then
        local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
        local dojo = teamComponent:GetEntrustQueueDataByQuestId(self._questVo.id)
        if dojo then
            ----如果正在委托中,直接打开委托页面
            UIModule.OpenDialog({id = Constants.UITypeIds.UIEntrustTasksDialog, parameters = {levelId = self._questVo.id}}, {{id = Constants.UITypeIds.UIFightMap}})
            return
        end
        UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self._questVo.id}}, {{id = Constants.UITypeIds.UIFightMap}})
    else
        if not self._isCopyOpen then
            GameUtils.Toast(localize("本轮未开放"))
        elseif not self._isCopyUnlcok then
            GameUtils.Toast(localize("副本未解锁"))
        elseif isUnlockLevel then
            GameUtils.Toast(localize("请完成前置关卡"))
        else
            GameUtils.Toast(GameUtils.GetUnlockDescr("1", checkString(self._questVo.level)))
        end
    end
end

function UIFightMapDailyQuestCell:SetCurLevelStatues(isTrue)
    --之前的特效修改为变大
    if isTrue then
        KTool.SetActive(self.curQuestIma.gameobject, true)
        CfUtils.SetScale(self.unLock, Vector3(1, 1, 1)) 
        KTool.SetActive(self.bigRewardBg, true)
        CfUtils.SetScale(self.rewardIcon, Vector3(0.7, 0.7, 0.7)) 
        self.titlebg.transform.localPosition = Vector3(-96, 142, 0)
        CfUtils.SetScale(self.entrust, Vector3(1, 1, 1)) 
        self.entrust.transform.localPosition = Vector3(0, -192, 0)
    else
        KTool.SetActive(self.curQuestIma.gameobject, false)
        CfUtils.SetScale(self.unLock, Vector3(0.4, 0.4, 0.4)) 
        KTool.SetActive(self.bigRewardBg, false)
        CfUtils.SetScale(self.rewardIcon, Vector3(1, 1, 1)) 
        self.titlebg.transform.localPosition = Vector3(-1, 48, 0)
        CfUtils.SetScale(self.entrust, Vector3(2.5, 2.5, 2.5)) 
        self.entrust.transform.localPosition = Vector3(0, -249, 0)
    end
end

function UIFightMapDailyQuestCell:OnDestroy()
    if not isNull(self) then
        ---删除计时器
        CDTimerModule.GetInstance():RemoveCD(self._time)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightMapDailyQuestCell